    },
    {
      "poi_id": "p27",
      "kind": "activity",
      "must_do_id": null,
      "note": "Egg coffee whipped thick as a cloud, sweet and strong. A proper little rest for the legs before the next wander."
    },
    {
      "poi_id": "p11",
      "kind": "activity",
      "must_do_id": null,
      "note": "Dried squid, bright fabric, busy hands and louder voices. Go hungry and leave with something you did not plan to buy."
    }
  ]
